import Foundation
import PeekabooAutomationKitTestSupport
import PeekabooFoundation
import Testing
@testable import PeekabooAgentRuntime
@testable import PeekabooAutomationKit

@MainActor
@Suite(.serialized)
struct MCPElementActionSnapshotAuthorityTests {
    @Test(arguments: [false, true], [false, true])
    func `confirmed results validate inside the lease before invalidating implicit latest`(
        noChange: Bool,
        requireExactWindow: Bool) async throws
    {
        let fixture = try await MCPSnapshotMutationTestFixture.make()
        let snapshot = try #require(await fixture.context.uiSnapshots.getSnapshot(id: fixture.snapshotID))
        let expected = try MCPElementActionSnapshotAuthority.expectedTargetIdentity(
            snapshot,
            requireExactWindow: requireExactWindow)
        let suppliedTarget = try #require(fixture.automation.uiAutomationOutcomeTargetIdentity)
        let outcome = noChange ? DesktopActionOutcome.confirmedNoChange() : Self.confirmedChange
        let supplied = Self.result(outcome: outcome, target: suppliedTarget)
        var events: [String] = []

        let completed = try await MCPElementActionSnapshotAuthority.withConfirmedMutation(
            snapshot: snapshot,
            expectedTarget: expected,
            context: fixture.context,
            operation: "Synthetic element mutation",
            mutate: {
                events.append("mutate")
                #expect(fixture.snapshots.beginCalls == [fixture.snapshotID])
                #expect(fixture.snapshots.finishCalls.isEmpty)
                await #expect(throws: PeekabooError.self) {
                    _ = try await fixture.storage.beginSnapshotMutation(snapshotId: fixture.snapshotID)
                }
                #expect(await fixture.context.uiSnapshots.getSnapshot(id: nil)?.id == fixture.snapshotID)
                return supplied
            },
            validateResult: { result in
                events.append("validate")
                #expect(fixture.snapshots.beginCalls == [fixture.snapshotID])
                #expect(fixture.snapshots.finishCalls.isEmpty)
                #expect(result.outcome == outcome)
                #expect(result.targetIdentity == suppliedTarget)
                #expect(result.payload.target == "T1")
            })

        #expect(events == ["mutate", "validate"])
        #expect(completed.result.outcome == supplied.outcome)
        #expect(completed.result.targetIdentity == supplied.targetIdentity)
        #expect(completed.result.payload.actionName == supplied.payload.actionName)
        #expect(completed.result.payload.newValue == supplied.payload.newValue)
        #expect(completed.invalidatedSnapshotID == (noChange ? nil : fixture.snapshotID))
        #expect(fixture.snapshots.finishCalls.count == 1)
        #expect(fixture.snapshots.finishCalls.first?.requiresFreshObservation == false)
        #expect(await fixture.context.uiSnapshots.getSnapshot(id: nil)?.id == (noChange ? fixture.snapshotID : nil))
        #expect(await fixture.context.uiSnapshots.getSnapshot(id: fixture.snapshotID) != nil)
        try await Self.expectReusable(fixture)
    }

    @Test(arguments: [false, true])
    func `pending and consumed leases reject before either caller closure`(consumed: Bool) async throws {
        let fixture = try await MCPSnapshotMutationTestFixture.make()
        let snapshot = try #require(await fixture.context.uiSnapshots.getSnapshot(id: fixture.snapshotID))
        let expected = try MCPElementActionSnapshotAuthority.expectedTargetIdentity(snapshot, requireExactWindow: true)
        let lease = try await fixture.storage.beginSnapshotMutation(snapshotId: fixture.snapshotID)
        if consumed {
            try await fixture.storage.finishSnapshotMutation(lease, requiresFreshObservation: true)
        }
        var mutationCalls = 0
        var validationCalls = 0

        let failure = await #expect(throws: DesktopActionFailure.self) {
            _ = try await MCPElementActionSnapshotAuthority.withConfirmedMutation(
                snapshot: snapshot,
                expectedTarget: expected,
                context: fixture.context,
                operation: "Synthetic element mutation",
                mutate: {
                    mutationCalls += 1
                    return Self.result(outcome: Self.confirmedChange, target: expected)
                },
                validateResult: { _ in validationCalls += 1 })
        }

        #expect(failure?.outcome.refusalReason == .targetUnavailable)
        #expect(failure?.outcome.retrySafety == .safe)
        #expect(failure?.targetReceipt == expected.actionTargetReceipt)
        #expect(mutationCalls == 0 && validationCalls == 0)
        #expect(fixture.snapshots.beginCalls == [fixture.snapshotID])
        #expect(fixture.snapshots.finishCalls.isEmpty)
    }

    @Test(arguments: RejectedResult.allCases)
    func `canonical outcome and target gates precede caller validation`(rejected: RejectedResult) async throws {
        let fixture = try await MCPSnapshotMutationTestFixture.make()
        let snapshot = try #require(await fixture.context.uiSnapshots.getSnapshot(id: fixture.snapshotID))
        let expected = try MCPElementActionSnapshotAuthority.expectedTargetIdentity(snapshot, requireExactWindow: true)
        let supplied = rejected.result(expected: expected)
        var mutationCalls = 0
        var validationCalls = 0

        let failure = await #expect(throws: DesktopActionFailure.self) {
            _ = try await MCPElementActionSnapshotAuthority.withConfirmedMutation(
                snapshot: snapshot,
                expectedTarget: expected,
                context: fixture.context,
                operation: "Synthetic element mutation",
                mutate: {
                    mutationCalls += 1
                    return supplied
                },
                validateResult: { _ in validationCalls += 1 })
        }

        #expect(failure?.outcome.retrySafety == .unsafe)
        #expect(failure?.outcome.projection.requiresFreshObservation == true)
        #expect(mutationCalls == 1 && validationCalls == 0)
        #expect(fixture.snapshots.finishCalls.count == 1)
        #expect(fixture.snapshots.finishCalls.first?.requiresFreshObservation == true)
        #expect(await fixture.context.uiSnapshots.getSnapshot(id: nil)?.id == fixture.snapshotID)
        try await Self.expectNotReusable(fixture)
    }

    @Test
    func `caller validation failure consumes the lease without replacing the failure`() async throws {
        let fixture = try await MCPSnapshotMutationTestFixture.make()
        let snapshot = try #require(await fixture.context.uiSnapshots.getSnapshot(id: fixture.snapshotID))
        let expected = try MCPElementActionSnapshotAuthority.expectedTargetIdentity(snapshot, requireExactWindow: true)
        let suppliedFailure = DesktopActionFailure.indeterminate(
            delivery: .init(mechanism: .accessibilityValue, mode: .background),
            evidence: .completionUnknown,
            unitCount: .one,
            message: "Synthetic typed result mismatch",
            hint: "Observe the exact target")
            .attributed(to: expected.actionTargetReceipt)
        var validationCalls = 0

        let failure = await #expect(throws: DesktopActionFailure.self) {
            _ = try await MCPElementActionSnapshotAuthority.withConfirmedMutation(
                snapshot: snapshot,
                expectedTarget: expected,
                context: fixture.context,
                operation: "Synthetic element mutation",
                mutate: { Self.result(outcome: Self.confirmedChange, target: expected) },
                validateResult: { _ in
                    validationCalls += 1
                    #expect(fixture.snapshots.beginCalls == [fixture.snapshotID])
                    #expect(fixture.snapshots.finishCalls.isEmpty)
                    throw suppliedFailure
                })
        }

        #expect(failure == suppliedFailure)
        #expect(validationCalls == 1)
        #expect(fixture.snapshots.finishCalls.count == 1)
        #expect(fixture.snapshots.finishCalls.first?.requiresFreshObservation == true)
        #expect(await fixture.context.uiSnapshots.getSnapshot(id: nil)?.id == fixture.snapshotID)
        try await Self.expectNotReusable(fixture)
    }

    @Test
    func `canonical predispatch refusal escapes unchanged and leaves authority reusable`() async throws {
        let fixture = try await MCPSnapshotMutationTestFixture.make()
        let snapshot = try #require(await fixture.context.uiSnapshots.getSnapshot(id: fixture.snapshotID))
        let expected = try MCPElementActionSnapshotAuthority.expectedTargetIdentity(snapshot, requireExactWindow: true)
        let suppliedFailure = DesktopActionFailure.preDispatchRefusal(
            reason: .targetUnavailable,
            message: "Synthetic refusal before input")
            .attributed(to: expected.actionTargetReceipt)

        let failure = await #expect(throws: DesktopActionFailure.self) {
            _ = try await MCPElementActionSnapshotAuthority.withConfirmedMutation(
                snapshot: snapshot,
                expectedTarget: expected,
                context: fixture.context,
                operation: "Synthetic element mutation",
                mutate: { throw suppliedFailure })
        }

        #expect(failure == suppliedFailure)
        #expect(fixture.snapshots.finishCalls.count == 1)
        #expect(fixture.snapshots.finishCalls.first?.requiresFreshObservation == false)
        #expect(await fixture.context.uiSnapshots.getSnapshot(id: nil)?.id == fixture.snapshotID)
        try await Self.expectReusable(fixture)
    }

    @Test(arguments: [false, true], [false, true])
    func `unknown errors and cancellation from either closure leave the lease pending`(
        cancellation: Bool,
        duringValidation: Bool) async throws
    {
        let fixture = try await MCPSnapshotMutationTestFixture.make()
        let snapshot = try #require(await fixture.context.uiSnapshots.getSnapshot(id: fixture.snapshotID))
        let expected = try MCPElementActionSnapshotAuthority.expectedTargetIdentity(snapshot, requireExactWindow: true)
        let suppliedError: any Error = cancellation ? CancellationError() : SyntheticError.completionUnknown
        var validationCalls = 0

        do {
            _ = try await MCPElementActionSnapshotAuthority.withConfirmedMutation(
                snapshot: snapshot,
                expectedTarget: expected,
                context: fixture.context,
                operation: "Synthetic element mutation",
                mutate: {
                    if !duringValidation {
                        throw suppliedError
                    }
                    return Self.result(outcome: Self.confirmedChange, target: expected)
                },
                validateResult: { _ in
                    validationCalls += 1
                    throw suppliedError
                })
            Issue.record("Unknown completion must not return success")
        } catch {
            if cancellation {
                #expect(error is CancellationError)
            } else {
                #expect(error as? SyntheticError == .completionUnknown)
            }
        }

        #expect(validationCalls == (duringValidation ? 1 : 0))
        #expect(fixture.snapshots.beginCalls == [fixture.snapshotID])
        #expect(fixture.snapshots.finishCalls.isEmpty)
        #expect(await fixture.context.uiSnapshots.getSnapshot(id: nil)?.id == fixture.snapshotID)
        try await Self.expectNotReusable(fixture)
    }

    @Test
    func `lease finalization failure prevents success and implicit invalidation`() async throws {
        let fixture = try await MCPSnapshotMutationTestFixture.make()
        let snapshot = try #require(await fixture.context.uiSnapshots.getSnapshot(id: fixture.snapshotID))
        let expected = try MCPElementActionSnapshotAuthority.expectedTargetIdentity(snapshot, requireExactWindow: true)
        fixture.snapshots.failFinish = true
        var validationCalls = 0

        let failure = await #expect(throws: DesktopActionFailure.self) {
            _ = try await MCPElementActionSnapshotAuthority.withConfirmedMutation(
                snapshot: snapshot,
                expectedTarget: expected,
                context: fixture.context,
                operation: "Synthetic element mutation",
                mutate: { Self.result(outcome: Self.confirmedChange, target: expected) },
                validateResult: { _ in validationCalls += 1 })
        }

        #expect(failure?.outcome.state == .indeterminate)
        #expect(failure?.outcome.retrySafety == .unsafe)
        #expect(failure?.targetReceipt == expected.actionTargetReceipt)
        #expect(validationCalls == 1)
        #expect(fixture.snapshots.finishCalls.count == 1)
        #expect(fixture.snapshots.finishCalls.first?.requiresFreshObservation == false)
        #expect(await fixture.context.uiSnapshots.getSnapshot(id: nil)?.id == fixture.snapshotID)
        try await Self.expectNotReusable(fixture)
    }

    private static var confirmedChange: DesktopActionOutcome {
        .confirmedChange(delivery: .init(mechanism: .accessibilityValue, mode: .background), unitCount: .one)
    }

    private static func result(
        outcome: DesktopActionOutcome?,
        target: DesktopTargetIdentity?) -> UIAutomationActionResult<ElementActionResult>
    {
        UIAutomationActionResult(
            payload: .init(target: "T1", actionName: "AXSetValue", anchorPoint: nil, newValue: "synthetic value"),
            outcome: outcome,
            targetIdentity: target)
    }

    private static func expectReusable(_ fixture: MCPSnapshotMutationTestFixture) async throws {
        let lease = try await fixture.storage.beginSnapshotMutation(snapshotId: fixture.snapshotID)
        try await fixture.storage.finishSnapshotMutation(lease, requiresFreshObservation: false)
    }

    private static func expectNotReusable(_ fixture: MCPSnapshotMutationTestFixture) async throws {
        await #expect(throws: PeekabooError.self) {
            _ = try await fixture.storage.beginSnapshotMutation(snapshotId: fixture.snapshotID)
        }
        #expect(try await fixture.snapshots.getDetectionResult(snapshotId: fixture.snapshotID) != nil)
        #expect(await fixture.context.uiSnapshots.getSnapshot(id: fixture.snapshotID) != nil)
    }

    private enum SyntheticError: Error, Equatable {
        case completionUnknown
    }

    enum RejectedResult: String, CaseIterable, Sendable {
        case unverified, missingOutcome, missingTarget, foreignTarget, foreground

        @MainActor
        func result(expected: DesktopTargetIdentity) -> UIAutomationActionResult<ElementActionResult> {
            let outcome: DesktopActionOutcome? = switch self {
            case .unverified:
                .dispatchedUnverified(
                    delivery: .init(mechanism: .accessibilityValue, mode: .background),
                    evidence: .deliveryAccepted)
            case .missingOutcome:
                nil
            case .foreground:
                .confirmedChange(delivery: .init(mechanism: .globalEvents, mode: .foreground), unitCount: .one)
            case .missingTarget, .foreignTarget:
                MCPElementActionSnapshotAuthorityTests.confirmedChange
            }
            let target: DesktopTargetIdentity? = switch self {
            case .missingTarget: nil
            case .foreignTarget: AutomationTestFixtures.linkedDesktopTarget().windowTargetIdentity
            default: expected
            }
            return MCPElementActionSnapshotAuthorityTests.result(outcome: outcome, target: target)
        }
    }
}

import CoreGraphics
import Foundation
import MCP
import PeekabooAutomationKit
import PeekabooFoundation
import TachikomaMCP
import Testing
@testable import PeekabooAgentRuntime

struct ObservationActionResultSupportTests {
    @Test
    func `typed refusal after confirmed observation dispatch remains retry unsafe`() throws {
        let target = try Self.target(windowID: 71)
        let priorOutcome = DesktopActionOutcome.confirmedChange(
            route: .bridge,
            delivery: Self.delivery,
            unitCount: DesktopActionOutcome.DispatchUnitCount(2))
        let laterFailure = DesktopActionFailure.preDispatchRefusal(
            route: .bridge,
            reason: .permissionDenied,
            message: "Rendering was refused")

        let error = ObservationActionResultSupport.preservingFailure(
            laterFailure,
            after: UIAutomationActionResult(payload: (), outcome: priorOutcome, targetIdentity: target),
            operation: "inspect_ui")
        let failure = try #require(error as? DesktopActionFailure)

        #expect(failure.outcome.state == .indeterminate)
        #expect(failure.outcome.delivery == Self.delivery)
        #expect(failure.outcome.dispatchState.unitCount?.rawValue == 2)
        #expect(failure.outcome.retrySafety == .unsafe)
        #expect(failure.targetReceipt == Self.receipt(windowID: 71))
    }

    @Test
    func `typed indeterminate follow up sums exact units and retains matching target`() throws {
        let target = try Self.target(windowID: 72)
        let priorOutcome = DesktopActionOutcome.dispatchedUnverified(
            route: .bridge,
            delivery: Self.delivery,
            evidence: .deliveryAccepted,
            unitCount: DesktopActionOutcome.DispatchUnitCount(2))
        let laterFailure = DesktopActionFailure.indeterminate(
            route: .bridge,
            delivery: Self.delivery,
            evidence: .responseLost,
            unitCount: DesktopActionOutcome.DispatchUnitCount(3),
            message: "Rendering response was lost")
            .attributed(to: Self.receipt(windowID: 72))

        let error = ObservationActionResultSupport.preservingFailure(
            laterFailure,
            after: UIAutomationActionResult(payload: (), outcome: priorOutcome, targetIdentity: target),
            operation: "see")
        let failure = try #require(error as? DesktopActionFailure)

        #expect(failure.outcome.state == .indeterminate)
        #expect(failure.outcome.evidence == .responseLost)
        #expect(failure.outcome.dispatchState.unitCount?.rawValue == 5)
        #expect(failure.outcome.retrySafety == .unsafe)
        #expect(failure.targetReceipt == Self.receipt(windowID: 72))
    }

    @Test
    func `typed follow up drops contradictory aggregate target`() throws {
        let target = try Self.target(windowID: 73)
        let priorOutcome = DesktopActionOutcome.dispatchedUnverified(
            route: .bridge,
            delivery: Self.delivery,
            evidence: .deliveryAccepted,
            unitCount: .one)
        let laterFailure = DesktopActionFailure.indeterminate(
            route: .bridge,
            delivery: Self.delivery,
            evidence: .completionUnknown,
            unitCount: .one,
            message: "A different target failed")
            .attributed(to: Self.receipt(windowID: 74))

        let error = ObservationActionResultSupport.preservingFailure(
            laterFailure,
            after: UIAutomationActionResult(payload: (), outcome: priorOutcome, targetIdentity: target),
            operation: "see")
        let failure = try #require(error as? DesktopActionFailure)

        #expect(failure.outcome.dispatchState.unitCount?.rawValue == 2)
        #expect(failure.outcome.retrySafety == .unsafe)
        #expect(failure.targetReceipt == nil)
    }

    @Test
    func `untyped follow up after confirmed dispatch preserves units target and retry unsafety`() throws {
        let target = try Self.target(windowID: 75)
        let priorOutcome = DesktopActionOutcome.confirmedChange(
            route: .bridge,
            delivery: Self.delivery,
            unitCount: DesktopActionOutcome.DispatchUnitCount(4))

        let error = ObservationActionResultSupport.preservingFailure(
            ObservationRenderingError(),
            after: UIAutomationActionResult(payload: (), outcome: priorOutcome, targetIdentity: target),
            operation: "inspect_ui")
        let failure = try #require(error as? DesktopActionFailure)

        #expect(failure.outcome.state == .indeterminate)
        #expect(failure.outcome.delivery == Self.delivery)
        #expect(failure.outcome.dispatchState.unitCount?.rawValue == 4)
        #expect(failure.outcome.retrySafety == .unsafe)
        #expect(failure.targetReceipt == Self.receipt(windowID: 75))
    }

    @Test
    func `metadata projects process generation without inventing a window`() throws {
        let target = try Self.processTarget(processIdentifier: 5201, processStartIdentity: 6201)
        let result = UIAutomationActionResult(
            payload: (),
            outcome: DesktopActionOutcome.dispatchedUnverified(
                delivery: Self.delivery,
                evidence: .deliveryAccepted,
                unitCount: .one),
            targetIdentity: target)

        let metadata = try ObservationActionResultSupport.metadata(merging: [:], result: result)
        let fields = try #require(metadata?.objectValue)
        let receipt = try #require(fields["target_receipt"]?.objectValue)

        #expect(receipt["pid"] == .int(5201))
        #expect(receipt["process_start_identity_decimal"] == .string("6201"))
        #expect(receipt["window_id"] == nil)
    }

    @Test
    func `typed failure retains compatible process scope across exact follow up`() throws {
        let target = try Self.processTarget(processIdentifier: 5202, processStartIdentity: 6202)
        let priorOutcome = DesktopActionOutcome.dispatchedUnverified(
            delivery: Self.delivery,
            evidence: .deliveryAccepted,
            unitCount: .one)
        let laterFailure = DesktopActionFailure.preDispatchRefusal(
            reason: .targetUnavailable,
            message: "Follow-up target disappeared")
            .attributed(to: DesktopActionTargetReceipt(
                processIdentifier: 5202,
                processStartIdentity: 6202,
                windowID: 82))

        let error = ObservationActionResultSupport.preservingFailure(
            laterFailure,
            after: UIAutomationActionResult(payload: (), outcome: priorOutcome, targetIdentity: target),
            operation: "see")
        let failure = try #require(error as? DesktopActionFailure)

        #expect(failure.targetReceipt == DesktopActionTargetReceipt(
            processIdentifier: 5202,
            processStartIdentity: 6202))
        #expect(failure.outcome.retrySafety == .unsafe)
    }

    @Test
    func `two dispatched phases drop incompatible process generation`() throws {
        let target = try Self.processTarget(processIdentifier: 5203, processStartIdentity: 6203)
        let priorOutcome = DesktopActionOutcome.dispatchedUnverified(
            delivery: Self.delivery,
            evidence: .deliveryAccepted,
            unitCount: .one)
        let laterFailure = DesktopActionFailure.indeterminate(
            delivery: Self.delivery,
            evidence: .completionUnknown,
            unitCount: .one,
            message: "Follow-up target changed generation")
            .attributed(to: DesktopActionTargetReceipt(
                processIdentifier: 5203,
                processStartIdentity: 7203))

        let error = ObservationActionResultSupport.preservingFailure(
            laterFailure,
            after: UIAutomationActionResult(payload: (), outcome: priorOutcome, targetIdentity: target),
            operation: "inspect_ui")
        let failure = try #require(error as? DesktopActionFailure)

        #expect(failure.targetReceipt == nil)
        #expect(failure.outcome.dispatchState.unitCount?.rawValue == 2)
        #expect(failure.outcome.retrySafety == .unsafe)
    }

    @Test
    func `untyped failure retains process-only target`() throws {
        let target = try Self.processTarget(processIdentifier: 5204, processStartIdentity: 6204)
        let priorOutcome = DesktopActionOutcome.confirmedChange(
            delivery: Self.delivery,
            unitCount: DesktopActionOutcome.DispatchUnitCount(2))

        let error = ObservationActionResultSupport.preservingFailure(
            ObservationRenderingError(),
            after: UIAutomationActionResult(payload: (), outcome: priorOutcome, targetIdentity: target),
            operation: "see")
        let failure = try #require(error as? DesktopActionFailure)

        #expect(failure.targetReceipt == DesktopActionTargetReceipt(
            processIdentifier: 5204,
            processStartIdentity: 6204))
        #expect(failure.outcome.dispatchState.unitCount?.rawValue == 2)
        #expect(failure.outcome.retrySafety == .unsafe)
    }

    @Test
    func `later unknown dispatch does not inherit prior no-dispatch exact target`() throws {
        let priorTarget = try Self.target(windowID: 91)
        let laterFailure = DesktopActionFailure.indeterminate(
            delivery: Self.delivery,
            evidence: .completionUnknown,
            unitCount: DesktopActionOutcome.DispatchUnitCount(2),
            message: "Follow-up dispatch target is unknown")

        let error = ObservationActionResultSupport.preservingFailure(
            laterFailure,
            after: UIAutomationActionResult(
                payload: (),
                outcome: DesktopActionOutcome.confirmedNoChange(),
                targetIdentity: priorTarget),
            operation: "see")
        let failure = try #require(error as? DesktopActionFailure)

        #expect(failure.targetReceipt == nil)
        #expect(failure.outcome.dispatchState.unitCount?.rawValue == 2)
        #expect(failure.outcome.retrySafety == .unsafe)
    }

    @Test
    func `unknown prior dispatch is not attributed to later no-dispatch target`() throws {
        let priorOutcome = DesktopActionOutcome.dispatchedUnverified(
            delivery: Self.delivery,
            evidence: .deliveryAccepted,
            unitCount: DesktopActionOutcome.DispatchUnitCount(2))
        let laterFailure = DesktopActionFailure.preDispatchRefusal(
            reason: .targetUnavailable,
            message: "Follow-up target disappeared")
            .attributed(to: Self.receipt(windowID: 92))

        let error = ObservationActionResultSupport.preservingFailure(
            laterFailure,
            after: UIAutomationActionResult(payload: (), outcome: priorOutcome, targetIdentity: nil),
            operation: "inspect_ui")
        let failure = try #require(error as? DesktopActionFailure)

        #expect(failure.targetReceipt == nil)
        #expect(failure.outcome.dispatchState.unitCount?.rawValue == 2)
        #expect(failure.outcome.retrySafety == .unsafe)
    }

    @Test
    func `only later dispatched phase owns aggregate process target`() throws {
        let priorTarget = try Self.target(windowID: 93)
        let laterTarget = DesktopActionTargetReceipt(
            processIdentifier: 5303,
            processStartIdentity: 6303)
        let laterFailure = DesktopActionFailure.indeterminate(
            delivery: Self.delivery,
            evidence: .completionUnknown,
            unitCount: DesktopActionOutcome.DispatchUnitCount(3),
            message: "Follow-up process dispatch is unknown")
            .attributed(to: laterTarget)

        let error = ObservationActionResultSupport.preservingFailure(
            laterFailure,
            after: UIAutomationActionResult(
                payload: (),
                outcome: DesktopActionOutcome.confirmedNoChange(),
                targetIdentity: priorTarget),
            operation: "see")
        let failure = try #require(error as? DesktopActionFailure)

        #expect(failure.targetReceipt == laterTarget)
        #expect(failure.outcome.dispatchState.unitCount?.rawValue == 3)
        #expect(failure.outcome.retrySafety == .unsafe)
    }

    @Test
    func `two dispatched phases retain compatible common process scope and sum units`() throws {
        let priorTarget = try Self.processTarget(processIdentifier: 5304, processStartIdentity: 6304)
        let priorOutcome = DesktopActionOutcome.dispatchedUnverified(
            delivery: Self.delivery,
            evidence: .deliveryAccepted,
            unitCount: DesktopActionOutcome.DispatchUnitCount(2))
        let laterFailure = DesktopActionFailure.indeterminate(
            delivery: Self.delivery,
            evidence: .completionUnknown,
            unitCount: DesktopActionOutcome.DispatchUnitCount(3),
            message: "Exact-window follow-up completion is unknown")
            .attributed(to: DesktopActionTargetReceipt(
                processIdentifier: 5304,
                processStartIdentity: 6304,
                windowID: 94))

        let error = ObservationActionResultSupport.preservingFailure(
            laterFailure,
            after: UIAutomationActionResult(payload: (), outcome: priorOutcome, targetIdentity: priorTarget),
            operation: "inspect_ui")
        let failure = try #require(error as? DesktopActionFailure)

        #expect(failure.targetReceipt == DesktopActionTargetReceipt(
            processIdentifier: 5304,
            processStartIdentity: 6304))
        #expect(failure.outcome.dispatchState.unitCount?.rawValue == 5)
        #expect(failure.outcome.retrySafety == .unsafe)
    }

    @Test
    func `two no-dispatch phases retain compatible process refusal scope`() throws {
        let priorTarget = try Self.target(
            processIdentifier: 5305,
            processStartIdentity: 6305,
            windowID: 95)
        let laterFailure = DesktopActionFailure.preDispatchRefusal(
            reason: .targetUnavailable,
            message: "Process-scoped follow-up was refused")
            .attributed(to: DesktopActionTargetReceipt(
                processIdentifier: 5305,
                processStartIdentity: 6305))

        let error = ObservationActionResultSupport.preservingFailure(
            laterFailure,
            after: UIAutomationActionResult(
                payload: (),
                outcome: DesktopActionOutcome.confirmedNoChange(),
                targetIdentity: priorTarget),
            operation: "see")
