private actor ReceiptWindowService: WindowManagementServiceProtocol, WindowMutationInventoryProviding {
    let window: ServiceWindowInfo
    let additionalWindow: ServiceWindowInfo?
    let inventoryWarnings: [String]

    init(
        window: ServiceWindowInfo,
        additionalWindow: ServiceWindowInfo? = nil,
        inventoryWarnings: [String] = [])
    {
        self.window = window
        self.additionalWindow = additionalWindow
        self.inventoryWarnings = inventoryWarnings
    }

    func closeWindow(target _: WindowTarget) async throws {}
    func minimizeWindow(target _: WindowTarget) async throws {}
    func maximizeWindow(target _: WindowTarget) async throws {}
    func moveWindow(target _: WindowTarget, to _: CGPoint) async throws {}
    func resizeWindow(target _: WindowTarget, to _: CGSize) async throws {}
    func setWindowBounds(target _: WindowTarget, bounds _: CGRect) async throws {}
    func focusWindow(target _: WindowTarget) async throws {}
    func listWindows(target _: WindowTarget) async throws -> [ServiceWindowInfo] {
        [self.window, self.additionalWindow].compactMap(\.self)
    }

    func windowMutationInventory(
        target _: WindowTarget) async throws -> DesktopTargetPlanning.Inventory<ServiceWindowInfo>
    {
        let windows = [self.window, self.additionalWindow].compactMap(\.self)
        if self.inventoryWarnings.isEmpty {
            return .complete(windows)
        }
        return .partial(windows, warnings: self.inventoryWarnings)
    }

    func getFocusedWindow() async throws -> ServiceWindowInfo? {
        nil
    }
}

import MCP
import PeekabooAutomationKit
import PeekabooFoundation
import TachikomaMCP

enum ObservationActionResultSupport {
    static func preservingFailure(
        _ error: any Error,
        after result: UIAutomationActionResult<some Sendable>?,
        operation: String) -> any Error
    {
        guard let result else { return error }
        return ObservationActionResultSemantics.preservingFailure(
            error,
            after: result,
            operation: operation)
    }

    static func metadata(
        merging base: [String: Value],
        result: UIAutomationActionResult<some Sendable>) throws -> Value?
    {
        var fields = base
        if let targetReceipt = result.actionTargetReceipt {
            fields["target_receipt"] = try Value(targetReceipt)
        }
        return try MCPToolResponseMetadataProjector.metadata(
            merging: fields,
            outcome: result.outcome)
    }

    static func standardErrorFields(_ error: any Error) -> [String: Value] {
        if let error = error as? DesktopActionFailure,
           let code = error.standardErrorCode
        {
            return ["error_code": .string(code.rawValue)]
        }
        guard let error = error as? PeekabooError else { return [:] }
        let code: StandardErrorCode? = switch error {
        case .accessibilityIncomplete:
            .accessibilityIncomplete
        case .timeout:
            .timeout
        default:
            nil
        }
        return code.map { ["error_code": .string($0.rawValue)] } ?? [:]
    }
}

