private final class LockedFlag: @unchecked Sendable {
    private let lock = NSLock()
    private var stored = false

    var value: Bool {
        self.lock.lock()
        defer { self.lock.unlock() }
        return self.stored
    }

    func set() {
        self.lock.lock()
        self.stored = true
        self.lock.unlock()
    }
}

